pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Progress in the stream (0..1)
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    let remaining_ratio = 1.0 - progress;

    // Residual ratios
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let mean_ratio = mean_residual / bin_capacity as f64;

    // Base penalty: sub‑quadratic for high residual
    let mut score = residual_ratio.powf(1.5) * 30.0;

    // Compare to mean residual
    if residual_ratio > mean_ratio {
        let diff = residual_ratio - mean_ratio;
        score += diff * diff * 60.0;
    } else {
        let diff = mean_ratio - residual_ratio;
        score -= diff * diff * 20.0;
    }

    // Tight‑fit bonus (only for bins that can accommodate the item)
    if bin_residual >= item_size {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= fit_ratio.powi(3) * 40.0; // stronger incentive for tighter fit
        if bin_residual <= 5 {
            score -= 10.0; // extra reward for very small residuals
        }
    }

    // Strong signal when only one bin can fit
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Look‑ahead: penalise leaving space the next item cannot fill
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        }
        // Extra penalty if the next item is larger and we have too little space
        if next_item_size > item_size && post_residual < next_item_size - 5 {
            score += 10.0;
        }
    }

    // Penalise the number of open bins (logarithmic growth)
    if open_bins_count > 0 {
        let open_penalty = (open_bins_count as f64).ln();
        score += open_penalty * 3.0;
    }

    // Near the end: prefer a new bin if future residual would be large
    if progress > 0.85 {
        let future_residual = (bin_residual as i32 - item_size as i32).max(0) as f64;
        let future_ratio = future_residual / bin_capacity as f64;
        if future_ratio > 0.25 {
            score += future_ratio.powi(2) * 30.0;
        }
    }

    // New‑bin candidate handling
    if bin_residual == bin_capacity {
        let new_residual = bin_capacity - item_size;
        let new_ratio = new_residual as f64 / bin_capacity as f64;
        if new_ratio > mean_ratio {
            score += 35.0; // penalise opening a bin that would be worse than the mean
        } else {
            score -= 20.0; // reward opening a bin that improves residual
        }
        // Extra incentive if the overall mean residual is already low
        if mean_ratio < 0.1 {
            score -= 5.0;
        }
    }

    // Slight bias against using many open bins when the stream has progressed far
    if remaining_ratio < 0.05 && open_bins_count > 3 {
        score += 15.0;
    }

    score
}

