    }

    // ----- Look‑ahead penalty -----
    if next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        score += 10.0 * miss * (next_item_size as f64 / bin_capacity as f64);
    }

    // ----- Last item small‑residual penalty -----
    if next_item_size == 0 && post_residual < 4 {
        score += 2.5;
    }

    // ----- Reward for multiple fitting bins -----
    if fitting_bins_count > 1
        && post_residual <= (mean_residual * 0.75) as u32
