        score -= 3.5;
    }

    // ----- Penalise bins already above the mean -----
    if bin_residual > mean_residual as u32 {
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.15;
    }

    // ----- Extra penalty for very high residuals -----
    if bin_residual > (bin_capacity * 60 / 100) {
        score += 1.2;
    }

    // ----- Empty bin candidate handling -----
    if bin_residual == bin_capacity {
        // Opening a new bin costs more as we open many bins
