pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // --- Base score: remaining capacity after placement ---
    let mut score = post_residual as f64;

    // --- Residual ratio shaping ---
    let ratio = post_residual as f64 / bin_capacity as f64;
    if ratio > 0.40 {
        // Large leftover: moderate quadratic penalty
        score += 0.15 * ratio.powi(2) * bin_capacity as f64;
    } else if ratio < 0.08 {
        // Tiny leftover: small reward
        score -= 0.40;
    }

    // --- Look‑ahead anticipation ---
    if next_item_size > 0 {
        let diff = next_item_size as i32 - post_residual as i32;
        if diff > 0 {
            // Next item larger than remaining space – heavy penalty
            let d = diff as f64;
            score += 3.0
                * d.powi(2)
                * (next_item_size as f64 / bin_capacity as f64).powi(2);
        } else if diff < -post_residual as i32 {
            // Next item too small for the remaining space – mild reward
            score -= 0.30;
        } else {
            // Next item fits – small reward proportional to spare space
            score -= 0.10 * (post_residual as f64 - next_item_size as f64);
        }
    }

    // --- Small residual reward ---
    if post_residual < (mean_residual * 0.07) as u32 {
        score -= 0.60;
    }

    // --- Residual variance penalty ---
    let bin_diff = bin_residual as f64 - mean_residual;
    if bin_diff.abs() > 0.20 * mean_residual {
        score += (bin_diff / mean_residual).powi(2) * 0.30;
    } else {
        score -= 0.15;
    }

    // --- Compactness reward ---
    if fitting_bins_count > 10 {
        score -= 2.0;
    } else if fitting_bins_count > 6 {
        score -= 1.0;
    }

    // --- Open bins penalty ---
    if open_bins_count > 12 {
        score += (open_bins_count - 12) as f64 * 0.15;
    }

    // --- New bin handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is costly
        score += 1.20;
        // Large items favor a fresh bin
        if item_size > bin_capacity * 85 / 100 {
            score -= 4.50;
        }
        // Very small items discourage opening a new bin
        if item_size < bin_capacity * 12 / 100 {
            score += 2.50;
        }
        // Many fitting bins discourage a new bin
        if fitting_bins_count > 8 {
            score += 0.50;
        }
        // Early in the stream, opening a new bin is more expensive
        if step_index < total_items / 2 {
            score += 0.80;
        }
    }

    // --- Progress penalty (logistic) ---
    let progress = step_index as f64 / total_items as f64;
    let logistic = 1.0 / (1.0 + (-7.0 * (progress - 0.5)).exp());
    score += logistic * 0.25;

    // --- End‑game penalty ---
    let remaining = total_items - step_index;
    if remaining < 4 && post_residual > bin_capacity * 55 / 100 {
        score += 1.20;
    }
    if remaining < 3 && post_residual as i32 == (bin_capacity - item_size) as i32 {
        score -= 1.00;
    }

    // --- Dead space ratio penalty ---
    if ratio > 0.25 && ratio > 0.40 {
        score += 0.50;
    }

    score
